import type { Metadata } from "next";
import { Inter } from "next/font/google";
import "./globals.css";

import Header from "@/components/layout/Header";
import Footer from "@/components/layout/Footer";
import Providers from "./providers"; // Jo file abhi upar banayi hai

// Inter font B2B UI ke liye sabse best aur exact match karta hai
const inter = Inter({
  subsets: ["latin"],
  variable: "--font-sans",
  display: "swap",
});

export const metadata: Metadata = {
  title: "B2B Marketplace",
  description: "India's Trusted B2B Marketplace",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className={`${inter.variable} h-full antialiased`}>
      <body className="min-h-full flex flex-col font-sans bg-[var(--color-surface-light)] text-slate-800">
        <Providers>
          <Header />

          {children}


          <Footer />
        </Providers>

      </body>
    </html>
  );
}
